parameters.jsCode:
// Lee texto desde text, caption o callback; si no hay, usa cadena vacía.
const textRaw =
  ($json?.message?.text)
  ?? ($json?.message?.caption)
  ?? ($json?.callback_query?.data)
  ?? "";

// Normaliza SIEMPRE como string
function normalize(s){
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g,"")
    .replace(/\s+/g," ")
    .trim();
}

function aboutRegimenIntent(t){
  const txt = normalize(t);

  const must = [
    /\bregimen fiscal\b/,
    /\bcambiar (de )?regimen\b/,
    /\balta (en )?regimen\b/,
    /\bobligac(ion|iones) (del )?regimen\b/,
    /\bresico\b|\brif\b|\bactividades? empresariales?\b|\basalariad[oa]s?\b|\barrendamiento\b/
  ];
  const interrogatives = [
    /\bcomo\b/, /\bque\b/, /\bqué\b/, /\bdonde\b/, /\bdónde\b/, /\?/,
    /\bpuedo\b/, /\bdebo\b/
  ];
  const anti = [
    /\bcomprobante fiscal\b|\bcfdi\b|\bdomicilio fiscal\b|\bejercicio fiscal\b|\bcedula (fiscal|rfc)\b/
  ];

  const hasMust = must.some(r=>r.test(txt)) || (/\bregimen\b/.test(txt) && /\bfiscal\b/.test(txt));
  const hasQ = interrogatives.some(r=>r.test(txt));
  const hasAnti = anti.some(r=>r.test(txt));

  const isRegimenQuestion = (hasMust && hasQ) && !hasAnti;
  const maybe = (!isRegimenQuestion && (/\bregimen\b|\bfiscal\b|\bresico\b|\brif\b/.test(txt)) && !hasAnti);

  return { isRegimenQuestion, maybe, txt };
}

const out = aboutRegimenIntent(textRaw);

return [{
  json: {
    ...$json,
    text_raw: textRaw,
    text_norm: out.txt,
    intent: out.isRegimenQuestion ? 'regimen_fiscal' : 'otro',
    intent_maybe: !!out.maybe
  }
}];

const items = $input.all();
const curpRegex = /\b([A-ZÑ]{4}\d{6}[A-ZÑ]{6}\d{2})\b/i;

const extractedCurps = items.map((item) => {
  const text = item?.json?.message?.text ?? "";
  const match = text.match(curpRegex);

  return {
    curp: match ? match[1].toUpperCase() : null
  };
});

return extractedCurps;
